CREATE TABLE "Admin" ("id" TEXT NOT NULL,"username" TEXT NOT NULL,"passwordHash" TEXT NOT NULL,"role" TEXT NOT NULL DEFAULT 'owner',"totpSecret" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Admin_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "Admin_username_key" ON "Admin"("username");
CREATE TABLE "AdminSession" ("id" TEXT NOT NULL,"adminId" TEXT NOT NULL,"tokenHash" TEXT NOT NULL,"expiresAt" TIMESTAMP(3) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "AdminSession_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "AdminSession_tokenHash_key" ON "AdminSession"("tokenHash"); CREATE INDEX "AdminSession_expiresAt_idx" ON "AdminSession"("expiresAt");
CREATE TABLE "SiteConfig" ("id" TEXT NOT NULL,"version" INTEGER NOT NULL DEFAULT 1,"draft" JSONB NOT NULL,"published" JSONB NOT NULL,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "SiteConfig_pkey" PRIMARY KEY ("id"));
CREATE TABLE "PublishVersion" ("id" TEXT NOT NULL,"version" INTEGER NOT NULL,"payload" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"createdBy" TEXT NOT NULL,CONSTRAINT "PublishVersion_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "PublishVersion_version_key" ON "PublishVersion"("version");
CREATE TABLE "Game" ("id" TEXT NOT NULL,"slug" TEXT NOT NULL,"title" JSONB NOT NULL,"description" JSONB NOT NULL,"category" TEXT NOT NULL,"provider" TEXT,"image" TEXT,"imageAlt" JSONB NOT NULL,"launchUrl" TEXT,"isActive" BOOLEAN NOT NULL DEFAULT true,"sortOrder" INTEGER NOT NULL DEFAULT 0,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Game_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "Game_slug_key" ON "Game"("slug");
CREATE TABLE "Media" ("id" TEXT NOT NULL,"key" TEXT NOT NULL,"url" TEXT NOT NULL,"mimeType" TEXT NOT NULL,"size" INTEGER NOT NULL,"width" INTEGER,"height" INTEGER,"alt" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Media_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "Media_key_key" ON "Media"("key");
CREATE TABLE "WinDemo" ("id" TEXT NOT NULL,"day" TEXT NOT NULL,"revealAt" TIMESTAMP(3) NOT NULL,"maskedName" TEXT NOT NULL,"amount" INTEGER NOT NULL,"currency" TEXT NOT NULL DEFAULT 'AMD',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "WinDemo_pkey" PRIMARY KEY ("id")); CREATE INDEX "WinDemo_day_revealAt_idx" ON "WinDemo"("day","revealAt");
CREATE TABLE "AuditLog" ("id" TEXT NOT NULL,"adminId" TEXT NOT NULL,"action" TEXT NOT NULL,"entity" TEXT NOT NULL,"entityId" TEXT,"before" JSONB,"after" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "AuditLog_pkey" PRIMARY KEY ("id")); CREATE INDEX "AuditLog_createdAt_idx" ON "AuditLog"("createdAt");
ALTER TABLE "AdminSession" ADD CONSTRAINT "AdminSession_adminId_fkey" FOREIGN KEY ("adminId") REFERENCES "Admin"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "AuditLog" ADD CONSTRAINT "AuditLog_adminId_fkey" FOREIGN KEY ("adminId") REFERENCES "Admin"("id") ON DELETE RESTRICT ON UPDATE CASCADE;